[data-kind="sort"] .arow .atext::before,
[data-kind="match"] .arow .atext::before,
[data-kind="order"] .srow .srow-t::before,
[data-kind="multi"] .opt .opt-text::before {
  content: "";
  display: inline-block;
  width: 1.25rem;
  height: 1.25rem;
  margin-right: var(--space-2);
  vertical-align: -0.25rem;
  background-color: currentColor;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  opacity: 0.9;
}
[data-kind="sort"] [data-row="0"] .atext::before { -webkit-mask-image: var(--icon-check); mask-image: var(--icon-check); }
[data-kind="sort"] [data-row="1"] .atext::before { -webkit-mask-image: var(--icon-cloud); mask-image: var(--icon-cloud); }
[data-kind="sort"] [data-row="2"] .atext::before { -webkit-mask-image: var(--icon-magnify); mask-image: var(--icon-magnify); }
[data-kind="sort"] [data-row="3"] .atext::before { -webkit-mask-image: var(--icon-dots); mask-image: var(--icon-dots); }
[data-kind="match"] [data-row="0"] .atext::before { -webkit-mask-image: var(--icon-tag); mask-image: var(--icon-tag); }
[data-kind="match"] [data-row="1"] .atext::before { -webkit-mask-image: var(--icon-bubble); mask-image: var(--icon-bubble); }
[data-kind="match"] [data-row="2"] .atext::before { -webkit-mask-image: var(--icon-key); mask-image: var(--icon-key); }
[data-kind="match"] [data-row="3"] .atext::before { -webkit-mask-image: var(--icon-list); mask-image: var(--icon-list); }
[data-kind="order"] [data-idx="0"] .srow-t::before { -webkit-mask-image: var(--icon-list); mask-image: var(--icon-list); }
[data-kind="order"] [data-idx="1"] .srow-t::before { -webkit-mask-image: var(--icon-target); mask-image: var(--icon-target); }
[data-kind="order"] [data-idx="2"] .srow-t::before { -webkit-mask-image: var(--icon-play); mask-image: var(--icon-play); }
[data-kind="order"] [data-idx="3"] .srow-t::before { -webkit-mask-image: var(--icon-bubble); mask-image: var(--icon-bubble); }
[data-kind="multi"] .opt:nth-child(1) .opt-text::before { -webkit-mask-image: var(--icon-bubble); mask-image: var(--icon-bubble); }
[data-kind="multi"] .opt:nth-child(2) .opt-text::before { -webkit-mask-image: var(--icon-target); mask-image: var(--icon-target); }
[data-kind="multi"] .opt:nth-child(3) .opt-text::before { -webkit-mask-image: var(--icon-scroll); mask-image: var(--icon-scroll); }
[data-kind="multi"] .opt:nth-child(4) .opt-text::before { -webkit-mask-image: var(--icon-folder); mask-image: var(--icon-folder); }

widget.js:
(function () {
  var notes = [
    ["You ask: check my links", "Your words are the only thing the agent has to go on."],
    ["The agent reads the description line of every skill", "Not the name, and not the folder. The description is the line it matches."],
    ["One description matches your words", "This is where leading words pay off. Use the words you really type."],
    ["The skill runs", "It fired only because its description matched your request."]
  ];
  var at = 0;
  return function (values, root, changed) {
    if (changed === "reset") at = 0;
    else if (changed === "step") at = Math.min(at + 1, notes.length - 1);
    var svg = root.querySelector("svg.proc");
    if (svg) svg.setAttribute("data-at", String(at));
    var head = root.querySelector("[data-head]");
    var note = root.querySelector("[data-note]");
    if (head) head.textContent = notes[at][0];
    if (note) note.textContent = notes[at][1];
  };
})()

function (values, root) {
  var real = Number(values.real) || 0;
  var vague = Number(values.vague) || 0;
  var up = Math.min(100, real * 12);
  var down = Math.min(100, vague * 9);
  var net = Math.max(0, up - down);
  var span = 134;
  var svg = root.querySelector("svg.chart");
  if (!svg) return;
  svg.querySelector("[data-bar-a]").style.transform = "scaleY(" + (up / 100).toFixed(4) + ")";
  svg.querySelector("[data-bar-b]").style.transform = "scaleY(" + (down / 100).toFixed(4) + ")";
  svg.querySelector("[data-lab-a]").style.transform = "translateY(" + (-up / 100 * span).toFixed(2) + "px)";
  svg.querySelector("[data-lab-b]").style.transform = "translateY(" + (-down / 100 * span).toFixed(2) + "px)";
  svg.querySelector("[data-lab-a-text]").textContent = Math.round(up) + "%";
  svg.querySelector("[data-lab-b-text]").textContent = Math.round(down) + "%";
  svg.querySelector("[data-verdict-g]").style.transform = "translateY(" + (158 - net / 100 * span).toFixed(2) + "px)";
  svg.querySelector("[data-verdict-pct]").textContent = Math.round(net) + "%";
  var out = root.querySelector("[data-verdict-line]");
  if (out) out.textContent = say(net);
  function say(n) {
    if (n >= 75) return "Bets on. The description carries the words you really type, so the agent finds this skill.";
    if (n >= 45) return "A coin toss. One more word you really type would tip it.";
    if (n >= 20) return "Weak. The vague words are drowning the words that match.";
    return "Almost silent. Nothing here matches what you type, so the skill stays quiet.";
  }
}

function (values, root) {
  var on = !!values.only;
  var svg = root.querySelector("svg.state");
  if (!svg) return;
  svg.setAttribute("data-on", on ? "1" : "0");
  svg.querySelector("[data-flag]").textContent = on ? "true" : "false";
  svg.querySelector("[data-badge]").textContent = on ? "Waiting for you" : "Runs on its own";
  var note = root.querySelector("[data-note]");
  if (note) note.textContent = on
    ? "The agent leaves this skill alone. It runs only when you type its name, so nothing starts by surprise."
    : "The agent may start this skill on its own whenever your request sounds related.";
}
